import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJ0NkIPM.js";var i=JSON.parse(`{"title":"Airframe Setup (ArduPilot)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/qgc-user-guide/setup_view/airframe_ardupilot.md","filePath":"zh/qgc-user-guide/setup_view/airframe_ardupilot.md"}`),a={name:`zh/qgc-user-guide/setup_view/airframe_ardupilot.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="airframe-setup-ardupilot" tabindex="-1">Airframe Setup (ArduPilot) <a class="header-anchor" href="#airframe-setup-ardupilot" aria-label="Permalink to “Airframe Setup (ArduPilot)”">​</a></h1><p>Airframe Setup is used to select the frame class and type that matches your vehicle</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Airframe Setup is only available on <em>ArduCopter</em> and <em>ArduSub</em> vehicles (it is not shown for <em>ArduPilot</em> Rover or Plane vehicles).</p></div><h2 id="arducopter-airframe-setup" tabindex="-1">ArduCopter Airframe Setup <a class="header-anchor" href="#arducopter-airframe-setup" aria-label="Permalink to “ArduCopter Airframe Setup”">​</a></h2><p>To select the airframe in Copter:</p><ol><li><p>First select the <strong>Gear</strong> icon (Vehicle Setup) in the top toolbar and then <strong>Airframe</strong> in the sidebar.</p></li><li><p>Select the broad <em>Frame Class</em> for your vehicle:</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>You will need to reboot the vehicle for class changes to take effect.</p></div></li><li><p>Select the specific <em>Frame Type</em> for your vehicle:</p></li></ol><h2 id="ardusub" tabindex="-1">ArduSub Frame Setup <a class="header-anchor" href="#ardusub" aria-label="Permalink to “ArduSub Frame Setup”">​</a></h2><p>To select the frame type for Sub:</p><ol><li><p>First select the <strong>Gear</strong> icon (Vehicle Setup) in the top toolbar and then <strong>Frame</strong> in the sidebar.</p></li><li><p>Select the frame type that matches your vehicle (selecting a frame applies the selection).</p></li><li><p>Make sure that all <strong>green</strong> thrusters have <strong>clockwise</strong> propellers and all <strong>blue</strong> thrusters have <strong>counter-clockwise</strong> propellers (or vice-versa).</p><ul><li>You can also click <strong>Load Vehicle Default Parameters</strong> to load default parameter set for ArduSub.</li></ul></li></ol>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};